<h1>Order {{ $booking->id }}</h1><p>Status: {{ $booking->status }}</p><p>Payment processing is disabled.</p><h2>Deliveries</h2>@foreach($deliveries as $delivery)<article><p>Version {{ $delivery->version }}: {{ $delivery->status }}</p><p>{{ $delivery->note }}</p>@if($delivery->storage_path)<a href="{{ route('deliveries.download',[$booking,$delivery]) }}">Download private video</a>@else <span>Legacy external URL delivery (not secured)</span>@endif@if($booking->customer_id===auth()->id() && $delivery->status==='submitted')<form method="post" action="{{ route('deliveries.review',[$booking,$delivery]) }}">@csrf<button name="decision" value="accepted">Approve</button><button name="decision" value="revisions_requested">Request changes</button></form>@endif</article>@endforeach
